import java.util.Scanner;

public class FormularioValidado {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Name
        String nombre = "";
        while (nombre.isEmpty()) {
            System.out.print("Name: ");
            nombre = sc.nextLine().trim();
            if (nombre.isEmpty()) System.out.println("❌ The name cannot be empty");
        }

        // Age
        int edad = 0;
        boolean edadValida = false;
        while (!edadValida) {
            System.out.print("Age: ");
            if (sc.hasNextInt()) {
                edad = sc.nextInt();
                sc.nextLine();
                if (edad > 0 && edad < 150) {
                    edadValida = true;
                } else {
                    System.out.println("❌ Age must be between 1 and 149");
                }
            } else {
                System.out.println("❌ It must be a whole number");
                sc.next();
            }
        }

        // Email
        String email = "";
        while (!email.contains("@")) {
            System.out.print("Email: ");
            email = sc.nextLine().trim();
            if (!email.contains("@")) System.out.println("❌ The email must contain @");
        }

        // Phone
        String telefono = "";
        while (!telefono.matches("\\d{10}")) {
            System.out.print("Phone (10 digits): ");
            telefono = sc.nextLine().trim();
            if (!telefono.matches("\\d{10}")) System.out.println("❌ It must have exactly 10 digits");
        }

        System.out.println("\n=== Registration successful ===");
        System.out.println("Name: " + nombre);
        System.out.println("Age: " + edad);
        System.out.println("Email: " + email);
        System.out.println("Phone: " + telefono);

        sc.close();
    }
}
